$client = new GuzzleHttp\Client();

$response = $client->request('GET', 'https://apbugall.org/v2/movies', [
    'headers' => [
        'Authorization' => 'Bearer YOUR_AUTH_TOKEN',
        'Accept' => 'application/json',
    ]
]);

echo $response->getBody();

$ch = curl_init();

curl_setopt_array($ch, [
    CURLOPT_URL => 'https://apbugall.org/v2/movies',
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_CUSTOMREQUEST => 'GET',
    CURLOPT_HTTPHEADER => [
        'Authorization: Bearer YOUR_AUTH_TOKEN',
        'Accept: application/json',
    ],
]);

$response = curl_exec($ch);
curl_close($ch);

echo $response;

fetch('https://apbugall.org/v2/movies', {
    method: 'GET',
    headers: {
        'Authorization': 'Bearer YOUR_AUTH_TOKEN',
        'Accept': 'application/json'
    }
})
.then(response => response.json())
.then(data => console.log(data));

axios.get('https://apbugall.org/v2/movies', {
    headers: {
        'Authorization': 'Bearer YOUR_AUTH_TOKEN',
        'Accept': 'application/json'
    }
})
.then(response => console.log(response.data));

import { ofetch } from 'ofetch';

const data = await ofetch('https://apbugall.org/v2/movies', {
    method: 'GET',
    headers: {
